'use strict';
// Echoes of the Shattered Octave: service worker (Phase 18, team PWA).
//
// Offline play for a plain static site. Everything is relative to the worker's own scope, so it works at the root of a
// domain and under a GitHub Pages sub-path (https://owner.github.io/repo/) alike.
//
//   CORE  is precached when the worker installs: the page, scripts, styles, fonts, pictures and translations. The
//         install fails as a whole (and the version already running carries on) if any of it cannot be fetched, so a
//         half-cached game never goes live. Served cache-first.
//   MEDIA (music/, voices/) is cached the first time the game plays a file, or all at once on request from the page
//         (message "media-download"). Served cache-first, with Range requests answered from the cache (audio
//         elements ask for ranges, and a cache hit has to answer them as 206 or Safari refuses to play).
//   UPDATE: a new version installs in the background and WAITS. It takes over only when the page asks (message
//         "skip-waiting"), which is what the "A new version is ready" notice does when the player presses Reload,
//         so a running game is never swapped under the player.
//   The lists below are generated by tools/pwa/precache.js from index.html and the asset folders; test/pwa18.test.js
//   fails if they drift from them.
//
